#include <iostream>
#include <vector>
#include <queue>
#include <string>
using namespace std;
// 0=通道  1=牆壁  2=最短路徑  3=BFS 已探索

// ── BFS 尋找最短路徑 ─────────────────────────────────────────────
bool solveMaze(vector<vector<int>>& maze) {
    int rows = static_cast<int>(maze.size());
    int cols = static_cast<int>(maze[0].size());
    pair<int,int> start = {1, 0};
    pair<int,int> end   = {rows-2, cols-1};

    queue<pair<int,int>> q;
    vector<vector<pair<int,int>>> prev(
        rows, vector<pair<int,int>>(cols, {-1,-1}));
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));

    q.push(start);
    visited[start.first][start.second] = true;
    maze[start.first][start.second] = 3;

    const int dr[] = {-1, 0, 1, 0};
    const int dc[] = { 0, 1, 0,-1};

    bool found = false;
    while (!q.empty() && !found) {
        auto [r, c] = q.front(); q.pop();
        if (r == end.first && c == end.second) {
            found = true;
        } else {
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                    && maze[nr][nc] == 0 && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    prev[nr][nc] = {r, c};
                    q.push({nr, nc});
                    maze[nr][nc] = 3;                          // 標記已探索
                }
            }
        }
    }

    if (found) {
        int r = end.first, c = end.second;
        while (r != start.first || c != start.second) {
            maze[r][c] = 2;                      // 標記最短路徑
            auto [pr, pc] = prev[r][c];
            r = pr; c = pc;
        }
        maze[start.first][start.second] = 2;
    }
    return found;
}

// ── 列印迷宮 ──────────────────────────────────────────────────────
void printMaze(const vector<vector<int>>& maze) {
    for (const auto& row : maze) {
        for (int cell : row)
            cout << (cell==1 ? "██" : cell==2 ? "◆◆" : cell==3 ? "··" : "  ");
        cout << "\n";
    }
}

int main() {
    int rows, cols;
    cin >> rows >> cols;

    vector<vector<int>> maze(rows, vector<int>(cols));
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            cin >> maze[i][j];
        }
    }

    cout << "\n=== 原始迷宮 ===\n";
    printMaze(maze);

    bool solved = solveMaze(maze);

    cout << "\n=== 解答（2=最短路徑  3=已探索）===\n";
    printMaze(maze);
    cout << (solved ? "找到最短路徑！\n" : "無解！\n");
    return 0;
}
